// JSX is compiled to React.createElement()
const element = (
  <div className="container">
    <h1>Hello {user.name}</h1>
    <p>Current time: {new Date().toLocaleTimeString()}</p>
    {isLoggedIn && <button>Logout</button>}
    <img src="/logo.png" alt="Logo" />
  </div>
);

// Equivalent without JSX
const element = React.createElement(
  'div',
  { className: 'container' },
  React.createElement('h1', null, 'Hello ', user.name),
  React.createElement('p', null, 'Current time: ', new Date().toLocaleTimeString()),
  isLoggedIn && React.createElement('button', null, 'Logout'),
  React.createElement('img', { src: '/logo.png', alt: 'Logo' })
);

// JavaScript expressions in JSX
const items = ['Apple', 'Banana', 'Orange'];
const list = (
  <ul>
    {items.map((item, index) => (
      <li key={index}>{item}</li>
    ))}
  </ul>
);
